let pendingInputAt=-1,pendingRenderAt=0,inputCount=0;const inputLatencySamples=new Float32Array(256),inputProcessingSamples=new Float32Array(256);let inputProcessingCount=0;
function __tideInput(){const now=performance.now();__tideClock.input(now,__tideEligible(),state.mode);const start=performance.now();input();if(__tideEligible()){inputProcessingSamples[inputProcessingCount++%256]=performance.now()-start;pendingInputAt=now;pendingRenderAt=scene?.renderTotal()||0;}}

const BUILD='tidebound-r3-20261111';
const SAVE='stteak.tidebound.save.v1',PREFS='stteak.tidebound.preferences.v1';
const $=s=>document.querySelector(s),byId=id=>World.ISLANDS.find(i=>i.id===id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
