let prefs={music:.35,sfx:.65,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,quality:'auto',camera:matchMedia('(pointer:coarse)').matches?'follow':'overhead'},state=createState(1),storageAvailable=true,recoveryMessage='';
try{const raw=localStorage.getItem(SAVE);if(raw){const r=restore(raw);state=r.state;recoveryMessage=r.message;}}catch{recoveryMessage='保存資料無法讀取，已安全建立新航海日誌。';storageAvailable=false;}
try{const rawPrefs=localStorage.getItem(PREFS);let p={};try{p=JSON.parse(rawPrefs||'{}');}catch{ /* Damaged preferences use defaults without invalidating recovered voyage progress. */ }if(!p||typeof p!=='object'||Array.isArray(p))p={};for(const k of ['music','sfx'])if(Number.isFinite(p[k]))prefs[k]=Math.max(0,Math.min(1,p[k]));if(typeof p.reducedMotion==='boolean')prefs.reducedMotion=p.reducedMotion;if(['auto','low','high'].includes(p.quality))prefs.quality=p.quality;if(['overhead','follow'].includes(p.camera))prefs.camera=p.camera;}catch{storageAvailable=false;}
