 if(type==='map'){box.innerHTML=header('七島海圖','YOUR CHART · 北方在上')+`<div class="map-layout"><div class="map-wrap" id="map-wrap"><svg id="chart" viewBox="-290 -290 580 580" role="img" aria-label="七島海圖，橙色虛線為選定航線"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#a3c3b7" stroke-width=".6"/></pattern></defs><rect x="-500" y="-500" width="1000" height="1000" fill="url(#grid)"/><g id="map-world"></g></svg><div class="map-actions"><button data-zoom="1.2" aria-label="放大海圖">＋</button><button data-zoom="0.8" aria-label="縮小海圖">−</button><button id="map-reset">復位</button></div></div><div class="map-copy"><span class="eyebrow">航前讀海</span><h3>順流，也要看潮。</h3><p id="map-forecast"></p><label class="field">本趟航線<select id="route-choice"><option value="0">安全外海路</option><option value="1">潮窗捷徑</option></select></label><p id="route-description"></p><div id="map-branch-options"></div><div id="map-mission"></div><ul><li>△ 你的船，朝尖端前進</li><li>○ 港口外側可靠泊</li><li>▰ 礁石：漲潮可越、退潮繞行</li><li>↝ 海流：箭頭為流向</li><li>◎ 旋流：可由外側繞開</li><li>◇ 淺水潛點：靠岸後下潛</li><li>● 觀測浮標：可略過；取樣佔貨艙，返港 +3 印記</li></ul><p class="note">開啟海圖時暫停潮汐與氧氣。可單指拖曳、雙指縮放，或使用 ＋／−。</p></div></div>`;$('#route-choice').value=routeIndex;$('#route-choice').onchange=e=>{routeIndex=+e.target.value;drawMap();};setupMap();drawMap();
 }else if(type==='journal'){box.innerHTML=header('把發現畫進海圖。','FIELD JOURNAL')+`<p>已登錄 ${state.discoveries.length}/${World.DISCOVERIES.length} · 燈塔零件 ${state.parts.length}/3 · 委託 ${state.completed.length}/${World.CONTRACTS.length}。${state.storyComplete?'燈塔已點亮；自由航程開放。':'把三個淺水點的零件帶往北方燈塔，再回母港。'}</p><div class="journal-grid">${World.DISCOVERIES.map(d=>`<article class="journal-entry ${state.discoveries.includes(d.id)?'':'locked'}"><span class="eyebrow">${esc(d.kind)} · ${esc(byId(d.islandId)?.name)}</span><h3>${state.discoveries.includes(d.id)?esc(d.name):'尚未記錄'}</h3><p>${state.discoveries.includes(d.id)?esc(d.description):'在對應島嶼調查或完成淺水探索。'}</p></article>`).join('')}</div><div class="rule"></div><h3>自己的航程紀錄</h3><p>${recordText()}</p><button id="export-journal">匯出航海誌 JSON</button>`;$('#export-journal').onclick=()=>{const savedLocally=save();download('tidebound-journal.json',{buildId:BUILD,state:JSON.parse(serialize(state)),savedLocally});};
 }else if(type==='help'){box.innerHTML=header('第一次出海。','HOW TO SAIL')+`<p>先選一份委託與帆裝，升帆出港。沿海圖到達目標島外的碼頭，收帆減速，按 E 靠岸與調查。在同一趟航程完成清單的每項調查，再回母港交付；中途返母港會結束本趟，下趟需重新調查，永久圖鑑與零件仍保留。第一份要比較珊瑚灣、青根島、琉璃礁與白羽島，兩次淺潛同時取得燈塔零件。</p><p>海上金色浮標是可選觀測。取樣需距離 9 公尺內、速度不超過 1.4 m/s，佔 1 格普通貨艙，回港可換 3 印記；也可繼續直航挑戰最快紀錄。浮標不會撞傷船。</p><table class="controls-table"><tr><td>A / D、← / →</td><td>轉舵，船首決定前進方向</td></tr><tr><td>W / S、↑ / ↓</td><td>增加 / 減少帆力；不是前進 / 後退</td></tr><tr><td>Space</td><td>快速收帆，降低慣性</td></tr><tr><td>E</td><td>靠岸 / 調查 / 潛水取得物件</td></tr><tr><td>M / C / Esc</td><td>海圖 / 鏡頭 / 暫停</td></tr><tr><td>潛水 WASD</td><td>在淺水區移動；靠近發光目標按 E，浮出鍵隨時返船</td></tr></table><p>觸控使用左側轉舵鍵及右側帆力三檔；潛水會增加上下鍵。拖曳海面右半部或滑鼠右鍵拖曳可繞船看景。</p><p>▰ 退潮露礁，順流加速，◎ 旋流有週期。港口「等下一潮」可直接推進時間。所有危險都有外海安全路。船體低於 25% 時請返最近港；船沉或氧氣耗盡會救援，普通貨物減半，主線零件與圖鑑保留。</p><p>三段淺潛依序為珊瑚→琉璃→星盤。先完成觀察站，再操作每 6 秒開關的潮汐閥，最後預判每 8 秒橫掃的守鐘洋流。青綠標記是下一站；完成站會補滿氧氣。標準航程補給 15 分鐘，新零件補滿，120／60／15 秒會提醒；耗盡救援。母港可選悠遊模式。</p><p>離線不扣資源。每 15 秒、暫停、靠港與發現後自動保存；重載後按「繼續航程」恢復船位與氧氣。基礎修復免費。</p><button class="primary" data-close>明白了，去看海</button>`;
 }else if(type==='restart'){box.innerHTML=header('結束這趟航程？','RETURN TO HARBOR')+`<p>返回母港並免費修船。未交付普通貨物減半，主線零件、圖鑑和完成紀錄保留。</p><div class="actions"><button data-close>繼續航行</button><button id="confirm-restart" class="primary">確認返港</button></div>`;$('#confirm-restart').onclick=restartVoyage;
 }else if(type==='reset'){box.innerHTML=header('清除整本航海誌？','ERASE LOCAL PROGRESS')+`<p>此操作會清除本機的零件、圖鑑、委託與最佳紀錄。可先從航海誌匯出備份。</p><div class="actions"><button data-close>保留進度</button><button id="confirm-reset">清除並重新開始</button></div>`;$('#confirm-reset').onclick=()=>{state=createState(1);save();closeModal();invalidate();notify('已建立全新航海誌。');};
 }else{box.innerHTML=header(paused?'把時間留給海。':'聲音與畫面','PAUSED · 已暫停')+`<p>潮汐、船體與氧氣均已停止。關閉此視窗即可繼續。</p><div class="settings-grid"><label>音樂 <input id="music" type="range" min="0" max="1" step="0.05" value="${prefs.music}"></label><label>音效 <input id="sfx" type="range" min="0" max="1" step="0.05" value="${prefs.sfx}"></label><label><input id="reduced" type="checkbox" ${prefs.reducedMotion?'checked':''}> 減少浪高與鏡頭動態</label><label>畫質 <select id="quality"><option value="auto">自動 · 適合此裝置</option><option value="high">標準 · 陰影</option><option value="low">節能 · 低 DPR</option></select></label></div><div class="actions"><button class="primary" data-close>繼續</button><button id="show-help">操作說明</button><button id="save-voyage">儲存航程</button><button id="restart-button">重新準備出海</button></div><div class="rule"></div><p class="note">${BUILD} · 保存 schema 1 · 進度只存此瀏覽器，無雲端同步。</p><button id="reset-button">清除本機進度…</button>`;$('#quality').value=prefs.quality;for(const k of ['music','sfx'])$('#'+k).oninput=e=>{prefs[k]=+e.target.value;savePrefs();};$('#reduced').onchange=e=>{prefs.reducedMotion=e.target.checked;savePrefs();};$('#quality').onchange=e=>{prefs.quality=e.target.value;savePrefs();};$('#save-voyage').onclick=()=>notify(save()?'航程已儲存。下次可從此刻繼續。':'航程未能儲存。請保留此頁，或先匯出航海誌備份。',6500);$('#show-help').onclick=()=>showModal('help');$('#restart-button').onclick=()=>showModal('restart');$('#reset-button').onclick=()=>showModal('reset');}
 box.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal());box.querySelector('button')?.focus();updateAudio();
