function contractChecklist(id=state.contractId,planning=false){
  const progress=contractProgress(state,id);
  if(!progress?.objectives)return '';
  return `<ol class="contract-checklist" aria-label="${planning?'委託要求':'本趟調查進度'}">${progress.objectives.map(o=>`<li class="${!planning&&o.done?'done':''}">${!planning&&o.done?'✓ ':''}${esc(o.name)}${o.kind==='dive'?' · 淺潛':''}</li>`).join('')}</ol>${!planning&&progress.readyToDeliver?'<p class="note">本趟調查齊備，返回潮音港交付。</p>':''}`;
}
function observationAdvice(point){
  const flow=currentAt(point.x,point.z,state.time,state.seed);
  if(flow.strength>.12){
    const north=flow.z<0?'北':'南',east=flow.x<0?'西':'東';
    return `此處正向${Math.abs(flow.z)>Math.abs(flow.x)*2?north:Math.abs(flow.x)>Math.abs(flow.z)*2?east:north+east}流 ${flow.strength.toFixed(1)} m/s；靠近時收帆仍會漂移。可留在流道借力，或向外緣走穩定水路。`;
  }
  const reef=World.REEFS.find(r=>Math.hypot(r.x-point.x,r.z-point.z)<65);
  if(reef)return `${reef.name}${tideAt(state.time).height>reef.safeHeight?'目前水位可通行；仍要看下一潮預報':'目前露礁；沿海圖外側深水路繞行'}。`;
  return point.note;
}
function selectRoute(choice,optionId){
  markedObservation=null;doAction(()=>chooseRoute(state,choice.id,optionId));save();if(activeNavigation(state))$('#route-cancel').focus({preventScroll:true});
}
function renderRouteButtons(container,choice,inMap=false){
  const key=choice?`${choice.id}:${choice.direction}:${choice.entryIndex??0}:${choice.options.map(o=>`${o.id}:${o.available}`).join(',')}`:'';
  if(container.dataset.choice!==key){
    container.dataset.choice=key;container.replaceChildren();
    for(const option of choice?.options||[]){
      const button=document.createElement('button');button.type='button';button.disabled=option.available===false;
      const label=document.createElement('span');label.textContent=option.label;const cost=document.createElement('em'),detail=document.createElement('small');
      button.append(label,cost,detail);button.dataset.option=option.id;
      button.onclick=()=>{if(inMap)closeModal();selectRoute(choice,option.id);button.blur();};container.append(button);
    }
  }
  for(const option of choice?.options||[]){const button=container.querySelector(`[data-option="${option.id}"]`);if(button){button.querySelector('small').textContent=`${option.reason} ${option.condition||''}`;button.querySelector('em').textContent=`路點 ${option.distanceMetres} m · 約 ${option.estimatedSeconds} s`;}}
  if(inMap&&choice&&!container.querySelector('.route-estimate-note')){const note=document.createElement('p');note.className='route-estimate-note note';note.textContent='秒數按滿帆與目前流況估算到各自路點，不含轉舵、停船與後續航程。';container.append(note);}
}
function renderRouteChoice(){
  const card=$('#route-choice-card');shownRouteChoice=null;
  if(state.mode!=='sailing'||phase!=='running'||paused||overlay){card.hidden=true;return;}
  const nearSample=state.cargo.length<World.RIGS.find(r=>r.id===state.rigId).capacity&&World.encounterVariant(state).observations.some(p=>Math.hypot(p.x-state.boat.x,p.z-state.boat.z)<=20&&(p.id===markedObservation||state.boat.speed<=1.4)&&!state.voyage.harvested.includes(`observation:${p.id}`)&&!state.voyage.skippedObservations?.includes(p.id));
  // Passing an unmarked sample must not hide a new route decision. Give a
  // deliberately targeted sample, or a boat already slowing to collect, priority.
  if(nearSample&&!activeNavigation(state)){card.hidden=true;return;}
  const navigation=activeNavigation(state),choice=nearestRouteChoice(state);card.hidden=!choice&&!navigation;$('#route-cancel').hidden=!navigation;if(navigation&&!choice){$('#route-choice-title').textContent=navigation.label;$('#route-choice-context').textContent='依藍色路點手動掌舵；取消引導可恢復原本任務目標。';renderRouteButtons($('#route-options'),null);return;}if(!choice)return;shownRouteChoice=choice;
  $('#route-choice-title').textContent=choice.name;
  $('#route-choice-context').textContent=navigation?`目前沿「${navigation.label}」。可比較前方海況與進港角度，改選下一段藍色引導；仍需手動掌舵。`:'選擇後依左上方位手動掌舵；藍色路點只提供引導，不會自動操船。';
  renderRouteButtons($('#route-options'),choice);
}
$('#route-branch-map').onclick=()=>showModal('map');$('#route-cancel').onclick=()=>{doAction(()=>cancelRoute(state));save();};
function renderSurveyChoice(){
  const card=$('#survey-choice');shownObservation=null;
  if(state.mode!=='sailing'||phase!=='running'||paused||overlay||shownRouteChoice||activeNavigation(state)){card.hidden=true;return;}
  const candidates=World.encounterVariant(state).observations.filter(p=>!state.voyage.harvested.includes(`observation:${p.id}`)&&!state.voyage.skippedObservations?.includes(p.id)).map(p=>({...p,distance:Math.hypot(p.x-state.boat.x,p.z-state.boat.z)})).filter(p=>p.distance<=45).sort((a,b)=>(a.id===markedObservation?-1:b.id===markedObservation?1:a.distance-b.distance));
  const point=candidates[0];card.hidden=!point;if(!point)return;shownObservation=point;
  const capacity=World.RIGS.find(r=>r.id===state.rigId).capacity,full=state.cargo.length>=capacity;
  $('#survey-title').textContent=`${point.name} · ${Math.round(point.distance)} m`;
  $('#survey-detail').textContent=observationAdvice(point);
  $('#survey-tradeoff').textContent=`取樣佔 1 格貨艙，返港 +3 印記；直航可省停船時間。貨艙 ${state.cargo.length}/${capacity}。`;
  const button=$('#survey-sample');button.disabled=full;
  button.textContent=full?'貨艙已滿':point.distance>9?(markedObservation===point.id?'已標記 · 依方位前進':'標記取樣點'):state.boat.speed>1.4?'收帆減速':'取得取樣 E';
}
$('#survey-sample').onclick=()=>{
  const point=shownObservation;if(!point)return;unlock();
  if(point.distance>9){markedObservation=point.id;notify('取樣點已標記。依左上方位航行，接近浮標後收帆減速。');}
  else if(state.boat.speed>1.4){clearInput();state.boat.sail=0;notify('已收帆。航速降到 1.4 m/s 後按 E 取樣。');}
  else doAction(()=>collectObservation(state,point.id));
  $('#survey-sample').blur();render();
};
$('#survey-pass').onclick=()=>{if(!shownObservation)return;const id=shownObservation.id;if(markedObservation===id)markedObservation=null;doAction(()=>skipObservation(state,id));$('#survey-pass').blur();};
function targetInfo(){
  if(state.mode==='diving'){
    const site=World.DIVE_SITES.find(s=>s.id===state.activeDive)||World.DIVE_SITES.find(s=>s.islandId===state.currentIsland),target=World.diveTarget(state),stage=World.diveStage(state),tasks=state.diveTasks[site.id];
    return{title:`${stage.name} · ${tasks.completedStationIds.length}/${stage.stations.length}`,text:`${site?.name||'淺水探索'} · ${state.diveCollected?'已完成調查，可浮出回船。':`目標約 ${Math.round(Math.hypot((target?.x||0)-state.diver.x,(target?.z||0)-state.diver.z))} m；${target.name||site.partName}，4.5 m 內按 E。${stage.mechanic==='valves'?`閥門${World.valvePhase(state.time,state.voyage.variantId)<3?'開啟 ✓':'關閉'} · 每 6 秒循環。`:stage.mechanic==='guardian'?'避開移動圓圈；琥珀色為預警。':''}`} 氣泡補氧。`};
  }
  const navigation=activeNavigation(state);
  if(state.mode==='sailing'&&navigation){
    const p=navigation.target,d=Math.hypot(p.x-state.boat.x,p.z-state.boat.z),bearing=(Math.atan2(p.x-state.boat.x,-(p.z-state.boat.z))*180/Math.PI+360)%360;
    return{title:navigation.label,text:`路點 ${navigation.index+1}/${navigation.waypoints.length} · 約 ${Math.round(d)} 公尺 · 方位 ${Math.round(bearing)}°。依藍色路點掌舵，完成後繼續委託。`};
  }
  if(state.lighthouseFixed&&!state.storyComplete)return{title:'帶著光，回家。',text:'燈塔已修復。返回南方母港，完成故事。'};
  if(state.mode==='sailing'&&markedObservation){
    const point=World.encounterVariant(state).observations.find(p=>p.id===markedObservation);
    if(point&&!state.voyage.harvested.includes(`observation:${point.id}`)){
      const distance=Math.hypot(point.x-state.boat.x,point.z-state.boat.z),bearing=(Math.atan2(point.x-state.boat.x,-(point.z-state.boat.z))*180/Math.PI+360)%360;
      return{title:`取樣 · ${point.name}`,text:`約 ${Math.round(distance)} 公尺 · 方位 ${Math.round(bearing)}°。金色浮標 9 公尺內收帆，低速按 E；可隨時略過。`};
    }
    markedObservation=null;
  }
  if(state.parts.length===3&&!state.lighthouseFixed)return{title:'點亮北方燈塔。',text:'三個零件已齊備。前往北方燈塔靠泊，調查修復。'};
  if(state.mode==='harbor'){
    const planned=World.CONTRACTS.find(c=>c.id===selectedContract);
    return{title:planned?.name||'準備出海。',text:`準備前往${byId(planned?.islandId)?.name||'七島'}。先看航線與潮汐，再按 W 升帆。`};
  }
  const c=World.CONTRACTS.find(c=>c.id===state.contractId);
  if(c&&state.mode==='sailing'){
    const progress=contractProgress(state),has=progress.readyToDeliver,next=progress.nextObjective,i=byId(has?'harbor':next?.islandId||c.islandId),d=Math.hypot(state.boat.x-i.dock.x,state.boat.z-i.dock.z);
    return{title:has?'把發現帶回母港。':c.name,text:`${i.name} · ${Math.round((Math.atan2(i.dock.x-state.boat.x,-(i.dock.z-state.boat.z))*180/Math.PI+360)%360)}° · ${Math.round(d)} m · ${has?'靠泊交付後結算':`調查 ${progress.completedCount}/${progress.total} · ${next?.kind==='dive'?'靠岸後下潛':'到金色泊位收帆，按 E 靠岸'}`}`};
  }
  return{title:state.storyComplete?'七島，繼續探索。':'給海一盞燈。',text:state.storyComplete?'自由航程已開放。補齊圖鑑，或換帆裝與航線挑戰紀錄。':'尋找三個淺水零件，修復燈塔並安全返航。'};
}
