 if(!mini.dataset.built){$('#mini-world').innerHTML=World.ISLANDS.map(i=>`<circle data-island="${i.id}" cx="${i.x}" cy="${i.z}" r="${i.radius}" fill="#8eaf99" stroke="#eff3d7" stroke-width="4"/>`).join('')+World.REEFS.map(i=>`<circle cx="${i.x}" cy="${i.z}" r="${i.radius}" fill="#edab73" opacity=".6"/>`).join('')+'<line id="mini-line" stroke="#f9d295" stroke-width="3" stroke-dasharray="10 7"/><path id="mini-boat" d="M0 -12L8 10L0 6L-8 10Z" fill="#fff8df" stroke="#173e45" stroke-width="2"/>';mini.dataset.built='true';}
